# Test Conway's Game of Life variants on gap cells (value 1 = gap/0-color)
def life(zi, steps=1, wrap=True, R=13, C=14):
    cur={(r,c) for (r,c) in zi}
    for _ in range(steps):
        nxt=set()
        for r in range(13):
            for c in range(14):
                n=0
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        if dr==0 and dc==0: continue
                        rr,cc=r+dr,c+dc
                        if wrap: rr%=13; cc%=14
                        elif not(0<=rr<13 and 0<=cc<14): continue
                        if (rr,cc) in cur: n+=1
                if (r,c) in cur and n in (2,3): nxt.add((r,c))
                elif (r,c) not in cur and n==3: nxt.add((r,c))
        cur=nxt
    return cur
